destroy_worker.text:
void kthread_destroy_worker(struct kthread_worker *worker)
{
	struct task_struct *task;

	task = worker->task;
	if (WARN_ON(!task))
		return;

	kthread_flush_worker(worker);
	kthread_stop(task);
	WARN_ON(!list_empty(&worker->delayed_work_list));
	WARN_ON(!list_empty(&worker->work_list));
	kfree(worker);
}

flush_worker.text:
void kthread_flush_worker(struct kthread_worker *worker)
{
	struct kthread_flush_work fwork = {
		KTHREAD_WORK_INIT(fwork.work, kthread_flush_work_fn),
		COMPLETION_INITIALIZER_ONSTACK(fwork.done),
	};

	kthread_queue_work(worker, &fwork.work);
	wait_for_completion(&fwork.done);
}

stop.text:
int kthread_stop(struct task_struct *k)
{
	struct kthread *kthread;
	int ret;

	trace_sched_kthread_stop(k);

	get_task_struct(k);
	kthread = to_kthread(k);
	set_bit(KTHREAD_SHOULD_STOP, &kthread->flags);
	kthread_unpark(k);
	set_tsk_thread_flag(k, TIF_NOTIFY_SIGNAL);
	wake_up_process(k);
	wait_for_completion(&kthread->exited);
	ret = kthread->result;
	put_task_struct(k);

	trace_sched_kthread_stop_ret(ret);
	return ret;
}

worker_create.text:
int lsf_prepaid_cleanup_worker_create_full(void)
{
    DECLARE_COMPLETION_ONSTACK(done);
    struct lsf_cleanup_request *owned;
    struct lsf_cleanup_task_source source;
    struct task_struct *task;
    unsigned long task_bytes, alignment;
    void *address;
    int error;
    /* Do not silently omit enabled allocation/lock instrumentation. Its
     * private creation path is an explicit remaining profile boundary. */
    if (IS_ENABLED(CONFIG_DEBUG_LOCK_ALLOC))
        return -EOPNOTSUPP;
    error = lsf_prepaid_cleanup_task_geometry(&task_bytes, &alignment);
    if (error)
        return error;
    error = lsf_factory_cleanup_task_reserve(sizeof(*owned), task_bytes, alignment,
        &source, &address);
    if (error)
        return error;
    owned = address;
    owned->source = source;
    __kthread_init_worker(&owned->worker, "lsf/firmware-cleanup", &owned->lock_key);
    memcpy(owned->name, "lsf/firmware-cleanup", sizeof(owned->name));
    owned->create.full_name = owned->name;
    owned->create.threadfn = kthread_worker_fn;
    owned->create.data = &owned->worker;
    owned->create.node = NUMA_NO_NODE;
    owned->create.done = &done;
    spin_lock(&kthread_create_lock);
    if (lsf_cleanup_pending) {
        spin_unlock(&kthread_create_lock);
        return -EBUSY;
    }
    WRITE_ONCE(lsf_cleanup_pending, owned);
    spin_unlock(&kthread_create_lock);
    wake_up_process(kthreadd_task);
    /* Preserve the actual original create/complete ownership handshake.
     * Interrupting the opener never releases or reuses pending request memory. */
    if (unlikely(wait_for_completion_killable(&done))) {
        if (xchg(&owned->create.done, NULL))
            return -EINTR;
        wait_for_completion(&done);
    }
    task = owned->create.result;
    if (IS_ERR(task))
        return PTR_ERR(task);
    /* The REAL running entry completed this result. Bind only its
     * actual born Task to the already-charged original worker. The
     * full pending consumer remains disconnected until all active
     * observer/bootstrap gates are closed; no executor is claimed. */
    if (!lsf_factory_cleanup_worker_associate(source, owned, &owned->worker, task))
        return -EIO;
    wake_up_process(task);
    return 0;
}

factory_open.text:
static int lsf_factory_open(struct inode *inode, struct file *file)
{
    int error = -EOPNOTSUPP;
    (void)inode;
    /* Check BEFORE any candidate backing allocation or reference ownership.
     * Root credentials alone cannot assert closure or activate this backend. */
    if (!lsf_factory_selected_consumer())
        return error;
    if (lsf_prepaid_cleanup_irq_bootstrap_bytes() >
        LSF_BOOTSTRAP_CEILING - sizeof(factory) - sizeof(lsf_device_uevent_taps) -
            LSF_BACKING_BYTES - 2u * sizeof(void *))
        return -EOPNOTSUPP;
    if (!ns_capable(&init_user_ns, CAP_SYS_ADMIN))
        return -EPERM;
    if (!current->nsproxy || current->nsproxy->net_ns != &init_net)
        return -EOPNOTSUPP;
    mutex_lock(&factory_lock);
    if (factory.opened || READ_ONCE(factory.uncertain)) {
        error = -EBUSY;
        goto out;
    }
    error = lsf_factory_device_uevent_bank_enter();
    if (error)
        goto out;
    /* Never alloc_pages_exact: its transient rounded allocation could exceed
     * the charged extent. No retry, lower-order or generic allocator fallback. */
    factory.pages = alloc_pages(GFP_KERNEL | __GFP_ZERO | __GFP_NORETRY,
                                LSF_BACKING_ORDER);
    if (!factory.pages) {
        lsf_factory_device_uevent_bank_allocation_failed();
        error = -ENOMEM;
        goto out;
    }
    if (!lsf_prepaid_initialize(&factory.pool)) {
        WRITE_ONCE(factory.uncertain, 1);
        goto out;
    }
    factory.mm = current->mm;
    mmgrab(factory.mm);
    factory.tgid = get_pid(task_tgid(current));
    factory.cred = get_current_cred();
    factory.net = get_net(current->nsproxy->net_ns);
    factory.opened = 1;
    error = lsf_factory_device_initialize();
    if (error)
        goto out;
    error = lsf_prepaid_cleanup_worker_create();
    if (error) {
        WRITE_ONCE(factory.uncertain, 1);
        goto out;
    }
    file->private_data = &factory;
    error = 0;
out:
    mutex_unlock(&factory_lock);
    return error;
}

factory_release.text:
static int lsf_factory_release(struct inode *inode, struct file *file)
{
    unsigned int i;
    unsigned long flags;
    (void)inode;
    (void)file;
    mutex_lock(&factory_lock);
    spin_lock_irqsave(&pool_lock, flags);
    factory.pool.stopped = 1;
    WRITE_ONCE(factory.uncertain, 1);
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i)
        factory.pool.contexts[i].closed = 1;
    if (factory.device)
        (void)lsf_device_close(&factory.pool, factory.device->key);
    spin_unlock_irqrestore(&pool_lock, flags);
    /* A finite scan detaches only this original context's published cache
     * births under the original cache lock. Real callbacks still own them.
     * Genuine late descendants may be born after this scan; they stay charged
     * and cannot make this an acknowledgement of complete retirement. */
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i) {
        lsf_prepaid_netport_drain(&factory.contexts[i]);
        lsf_prepaid_sidcache_drain(&factory.contexts[i]);
    }
#ifdef LSF_STREAM_AVC_SOURCE
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i)
        lsf_prepaid_avc_drain(&factory.contexts[i]);
#endif
#ifdef LSF_STREAM_ROUTE_CACHE_SOURCE
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i)
        lsf_prepaid_route_cache_drain(&factory.contexts[i]);
#endif
    lsf_prepaid_device_sidcache_drain();
    lsf_prepaid_cleanup_sidcache_drain();
#ifdef LSF_STREAM_AVC_SOURCE
    lsf_prepaid_device_avc_drain();
    lsf_prepaid_cleanup_avc_drain();
#endif
    /* Device cache scans, like application scans, leave actual RCU
     * callbacks and any legitimate late descendants charged. No single
     * pass is complete retirement or an acknowledgement of backing. */
    /* Closing a descriptor is not final-free. No __free_pages, object release,
     * owner recycling, reference refund or reopen is justified here. Original
     * node backing and occupancy must stay in bounded native quarantine. */
    mutex_unlock(&factory_lock);
    return 0;
}
